// Generates element-extra-data.js from Bowserinator's PeriodicTableJSON (MIT).
// Adds columns not present in htmlConstants: electron affinity (kJ/mol) and
// successive ionization energies (kJ/mol). Keyed by atomic number 1..118.
//
// Run: node scripts/build-extra-data.cjs <path-to-PeriodicTableJSON.json>
// Re-run only when refreshing the data; the generated file is committed.

const fs = require("fs");
const path = require("path");

const src = process.argv[2];
if (!src) {
  console.error("usage: node scripts/build-extra-data.cjs <PeriodicTableJSON.json>");
  process.exit(1);
}
const data = JSON.parse(fs.readFileSync(src, "utf8")).elements;

const round = (x, d) => {
  const f = Math.pow(10, d);
  return Math.round(x * f) / f;
};

const out = {};
data.forEach((e) => {
  if (!(e.number >= 1 && e.number <= 118)) return;
  const rec = {};
  if (e.electron_affinity != null && isFinite(e.electron_affinity)) {
    rec.ea = round(e.electron_affinity, 3); // kJ/mol
  }
  if (Array.isArray(e.ionization_energies) && e.ionization_energies.length) {
    rec.ie = e.ionization_energies.map((v) => round(v, 1)); // kJ/mol
  }
  if (Object.keys(rec).length) out[e.number] = rec;
});

const header =
  "// AUTO-GENERATED by scripts/build-extra-data.cjs from Bowserinator's\n" +
  "// PeriodicTableJSON (MIT). Element data keyed by atomic number:\n" +
  "//   ea: electron affinity (kJ/mol)\n" +
  "//   ie: successive ionization energies (kJ/mol), 1st, 2nd, 3rd, ...\n" +
  "// Do not edit by hand; re-run the script to refresh.\n\n";

const body = "module.exports = " + JSON.stringify(out) + ";\n";
const dest = path.join(__dirname, "..", "element-extra-data.js");
fs.writeFileSync(dest, header + body);
console.log("Wrote " + dest + " with " + Object.keys(out).length + " elements");
